mapper.select:
SELECT id, message_id, user_id, content, status, retry_count, last_error, create_time, update_time
FROM push_task
WHERE message_id = #{messageId}

mapper.update:
UPDATE push_task
SET status = #{toStatus}, last_error = #{error}, update_time = NOW()
WHERE message_id = #{messageId} AND status = #{fromStatus}

UPDATE push_task
SET retry_count = retry_count + 1, update_time = NOW()
WHERE message_id = #{messageId}

UPDATE push_task
SET last_error = #{error}, update_time = NOW()
WHERE message_id = #{messageId}
